import random


def generate(seed: int = 0) -> list[str]:
    """All generated arguments stay within the statement bounds and follow the problem guarantees."""
    r = random.Random(seed)
    cases = [[1], [3, 9, 20, None, None, 15, 7]]
    seen = {tuple(x) for x in cases}
    while len(cases) < 600:
        n = r.randint(1, 100)
        a = [r.randint(-1000, 1000) for _ in range(n)]
        key = tuple(a)
        if key not in seen:
            seen.add(key)
            cases.append(a)
    return [f"candidate(root=tree_node({a!r}))" for a in cases]


